"""0/1 Knapsack — 1D DP filled from the back.

Walking the capacity downwards guarantees each item contributes at most once,
because the cells it reads have not been updated for this item yet.

Time: O(n * capacity)   Space: O(capacity)
"""
from typing import List


class Solution:
    def knapsack(self, weights: List[int], values: List[int], capacity: int) -> int:
        best = [0] * (capacity + 1)
        for weight, value in zip(weights, values):
            for c in range(capacity, weight - 1, -1):
                candidate = best[c - weight] + value
                if candidate > best[c]:
                    best[c] = candidate
        return best[capacity]
